import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-10-05","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-10-05","date":"2021-10-05T00:00:00.000Z","updated":"2021-10-08T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","监控"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-10-05.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-10-05.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-10-05.md"};function p(l,e,s,n,_,c){return o(),a("div",null,[...e[0]||(e[0]=[r("<p>在2021年10月5日的Ceph Orchestrator会议中，Ceph研发团队讨论并解决了几个关键问题：</p><ol><li><p><strong>Indiana Loopback配置问题</strong>：</p><ul><li>讨论了在CentOS 8和Ubuntu系统上配置Indiana Loopback的最新进展。</li><li>确认在CentOS 8上所有功能运行良好，但配置工具<code>nvme-cli</code>使用不便。</li><li>在Ubuntu上，默认内核不支持NVMe Loopback，存在bug，需要寻找更好的内核版本。</li><li>决定选择合适的内核版本支持NVMe Loopback，并编写技术任务文档，指导如何在LVM LVS前端添加NVMe Loopback配置。</li><li>测试相关功能，确保驱动组和设备应用的重装OSDs功能正常。</li></ul></li><li><p><strong>Dashboard监控堆栈问题</strong>：</p><ul><li>讨论了如何在Rook项目中手动配置Dashboard监控堆栈以支持Grafana和其他管理工具。</li><li>默认情况下，这些功能在Rook启动的Ceph集群中未启用。</li><li>决定提供详细的文档和步骤，指导用户手动配置监控堆栈。</li><li>提供演示视频和文档，帮助用户理解和配置监控堆栈。</li></ul></li></ol><p>会议还确认了设备在Linux系统中的表现正常，不会影响正常操作，并讨论了监控堆栈配置的问题，提出了相应的解决方案。</p><p>会议总结：本次会议主要解决了Indiana Loopback配置和Dashboard监控堆栈的问题，并制定了相应的后续行动计划。会议结束时，团队成员确认没有其他紧急议题需要讨论。</p>",4)])])}const u=t(i,[["render",p]]);export{h as __pageData,u as default};
